<?php
// Date-only file evidence; the day ceiling below is a comparison boundary, not an actual export timestamp.
function ed_snapshot($value){$v=trim((string)$value);$day=strlen($v)===10?report_date($v):substr(om_datetime($v,true),0,10);if($day>date('Y-m-d'))throw new Exception('Export Date cannot be in the future.');return $day.' 23:59:59';}
// A date-only file watermark is not a future clock time that can block a same-day manual event.
function ed_manual_day_boundary($o,$meta){return !empty($meta['manual'])&&!empty($o['last_snapshot'])&&substr($o['last_snapshot'],-8)==='23:59:59'&&substr($meta['snapshot'],0,10)===substr($o['last_snapshot'],0,10);}
function ot_order_meta($b,$no){$m=$b['meta'];if($b['kind']==='Status'&&!empty($m['export_time_corrections'][hash('sha256',(string)$no)])){$m['original_export_time']=$m['snapshot'];$m['snapshot']=$m['export_time_corrections'][hash('sha256',(string)$no)];}if($b['kind']==='Status'&&empty($m['manual'])){$m['original_export_time']=$m['original_export_time']??$m['snapshot'];$m['snapshot']=ed_snapshot($m['snapshot']);$m['export_date']=substr($m['snapshot'],0,10);$m['snapshot_precision']='date';}return $m;}

function ot_candidates($orders){return array_values(array_filter($orders,fn($r)=>!empty($r['order_record'])&&!empty($r['errors'])&&(bool)array_filter($r['errors'],fn($e)=>(bool)preg_match('/after Export Date|after Export Time|snapshot predates|Older export conflicts with the recorded timeline/i',$e))));}
function ot_review_batch($id,$revision){om_require();$b=om_upload($id);om_owner($b);if($b['kind']!=='Status'||!empty($b['meta']['manual']))throw new Exception('Use an unconfirmed file-based Update Status review.');if((int)$b['revision']!==(int)$revision)throw new Exception('Review changed. Refresh and preview the correction again.');return $b;}
function ot_plan($id,$revision,$target,$snapshot,$reason){$b=ot_review_batch($id,$revision);$snapshot=ed_snapshot($snapshot);$reason=process_reason($reason);$before=om_plan($b);$eligible=ot_candidates($before['orders']);$selected=array_values(array_filter($eligible,fn($r)=>$target==='*'||(string)$r['order']===(string)$target));if(!$selected)throw new Exception('Select a Needs Checking order with an Export Date issue. Other rows cannot be edited here.');$orders=[];$amended=$b;
 foreach($selected as $row){$minimum='';foreach(om_source_date_lines($row['lines']) as $line)foreach(['created','ship_at','delivered_at'] as $key)if(!empty($line[$key])&&$line[$key]>$minimum)$minimum=$line[$key];if($minimum!==''&&$snapshot<$minimum)throw new Exception('Order '.$row['order'].': Export Date must be at least '.substr($minimum,0,10).', the latest event in its source rows. Enter the actual export date.');$orders[]=(string)$row['order'];$amended['meta']['export_time_corrections'][hash('sha256',$row['order'])]=$snapshot;}
 $after=om_plan($amended);$results=[];foreach($selected as $old)foreach($after['orders'] as $new)if($new['order']===$old['order'])$results[]=['order'=>$old['order'],'before'=>ot_order_meta($b,$old['order'])['snapshot'],'after'=>$snapshot,'before_errors'=>$old['errors'],'remaining_errors'=>$new['errors'],'decision'=>os_decision_label($new),'stock_effect_on_confirmation'=>os_effect($new)];return ['id'=>(int)$id,'revision'=>(int)$revision,'target'=>(string)$target,'snapshot'=>$snapshot,'reason'=>$reason,'orders'=>$orders,'original_digest'=>$before['digest'],'amended_digest'=>$after['digest'],'results'=>$results];
}
function ot_apply($plan){om_require();return process_transaction(function()use($plan){om_query('SELECT id FROM om_uploads WHERE id=? FOR UPDATE',[$plan['id']])->fetch();$fresh=ot_plan($plan['id'],$plan['revision'],$plan['target'],$plan['snapshot'],$plan['reason']);if($fresh!==$plan)throw new Exception('Orders, stocks or review changed. Preview the Export Date correction again.');$b=om_upload($plan['id']);foreach($plan['results'] as $r){$b['meta']['export_time_corrections'][hash('sha256',$r['order'])]=$plan['snapshot'];$o=om_find($b['platform'],$b['shop'],$r['order']);om_event($o['id'],$b['id'],'Export date corrected',['source'=>'Existing status upload review','reason'=>$plan['reason'],'original_export_time'=>$b['meta']['snapshot'],'previous_export_time'=>$r['before'],'corrected_export_time'=>$plan['snapshot'],'remaining_validation'=>$r['remaining_errors'],'stock_changed'=>false]);}om_query('UPDATE om_uploads SET meta_json=?,revision=revision+1 WHERE id=?',[json_encode($b['meta']),$b['id']]);audit('Correct order export date','Order Monitoring',(string)$b['id'],json_encode(['orders'=>$plan['orders'],'snapshot'=>$plan['snapshot'],'reason'=>$plan['reason'],'stock_changed'=>false]));return count($plan['orders']);});}
function ot_history_report($id){if(!access_report_allowed('registration_process'))throw new Exception('Detailed upload correction history is restricted to operational and audit roles.');$b=om_upload($id);$rows=[];foreach(om_query("SELECT e.*,o.order_no,u.name actor FROM om_events e JOIN om_orders o ON o.id=e.order_id LEFT JOIN users u ON u.id=e.user_id WHERE e.upload_id=? AND e.event_type IN ('Export time corrected','Export date corrected') ORDER BY e.id DESC",[$id]) as $e){$d=json_decode($e['details_json'],true)?:[];$rows[]=[$e['created_at'],$b['platform'],$e['order_no'],substr($d['original_export_time'],0,10),substr($d['previous_export_time'],0,10),substr($d['corrected_export_time'],0,10),$d['reason'],$e['actor'],0,$b['filename']];}return ['title'=>'Export Date Correction History #'.$id,'headers'=>['Recorded At','Platform','Order ID','Original File Export Date','Previous Effective Time','Corrected Effective Time','Reason','User','Physical Stock Change','File'],'rows'=>$rows];}
function ot_panel($b,$orders){if($b['kind']!=='Status'||!empty($b['meta']['manual']))return;$editable=$b['status']==='Review'&&om_allowed()&&(access_profile()==='Admin'||(int)$b['created_by']===current_user()['id']);$eligible=$editable?ot_candidates($orders):[];if($eligible){$latest='';foreach($eligible as $row)foreach(om_source_date_lines($row['lines']) as $line)foreach(['created','ship_at','delivered_at'] as $field)if(!empty($line[$field])&&$line[$field]>$latest)$latest=$line[$field];echo '<details class="os-rules"><summary>Correct Export Date · '.count($eligible).' date-related Needs Checking orders</summary><p>Correct the actual export date without uploading again. Only selected date-related Needs Checking rows are revalidated; other rows keep their original Export Date.</p><p><b>Latest source event:</b> '.e($latest?substr($latest,0,10):'Not available').' · this is a minimum check, not the file export date.</p>';om_form('om_export_time_preview',['upload_id'=>$b['id'],'revision'=>$b['revision']]);echo '<div class="os-fields"><label>Apply to<select name="target"><option value="*">All '.count($eligible).' eligible Needs Checking orders</option>';foreach($eligible as $row)echo '<option value="'.e($row['order']).'">'.e($row['order']).'</option>';echo '</select></label><label>Actual Export Date<input name="snapshot" type="date" value="'.e(substr($b['meta']['snapshot'],0,10)).'" max="'.date('Y-m-d').'" required></label><label>Reason / supporting reference<input name="reason" minlength="3" maxlength="2000" required></label></div><p class="small muted">Use the actual export date. Source event dates are shown under View Dates / Posting Basis. The latest event is a minimum, not proof of when the file was exported.</p><button class="btn secondary">Preview Export Date Correction</button></form></details>';}
 $saved=$_SESSION['ot_preview'][$b['id']]??null;if($editable&&$saved){$p=$saved['plan'];if($p['revision']!=$b['revision'])echo '<p class="alert warn">The Export Date preview is stale. Preview again.</p>';else{echo '<section class="card"><h3>Review Export Date Correction</h3>';om_table(['Order ID','Before','Corrected','After revalidation'],array_map(fn($r)=>[$r['order'],substr($r['before'],0,10),substr($r['after'],0,10),$r['remaining_errors']?implode(' · ',$r['remaining_errors']):$r['decision']],array_slice($p['results'],0,10)));echo '<p>'.count($p['orders']).' affected orders · showing first 10 · stock effect on Save: 0.</p>';om_form('om_export_time_apply',['upload_id'=>$b['id'],'correction_token'=>$saved['token']]);echo '<label class="om-inline"><input type="checkbox" name="correction_ack" value="1" required> I verified the actual export date and selected orders.</label><button class="btn primary">Save Export Date &amp; Revalidate · No Stock Change</button></form><p class="small muted">Confirm Valid Updates remains separate. Unrelated mapping, quantity and stock errors are not bypassed.</p></section>';}}
 if(!empty($b['meta']['export_time_corrections']))echo '<p class="small muted">Export Date corrections apply only to '.count($b['meta']['export_time_corrections']).' selected rows. Original file date: '.e(substr($b['meta']['snapshot'],0,10)).'. <a href="order_monitor_action.php?download=export_time_history&amp;id='.(int)$b['id'].'">Download Correction History</a></p>';
}
